use phonebook_rt as rt;
use std::collections::BTreeMap;

/// 000-0000001  NOT_BLANK
///
/// A local extension: this is custom logic, not a registered address.
fn not_blank(line: &String) -> bool {
    let line: String = line.clone();
    let trimmed: String = rt::text::trim(&line);
    let blank: bool = trimmed.is_empty();
    let keep: bool = (!blank);
    keep
}

fn main() {
    let text: String = rt::io_::read_text_file(&"examples/data/notes.txt".to_string());
    let lines: Vec<String> = rt::text::split_lines(&text);
    let kept: Vec<String> = lines.iter().cloned().filter(|_pb_x| not_blank(_pb_x)).collect::<Vec<_>>();
    let n: i64 = (kept.len() as i64);
    rt::core::print_value(&n);
}
